mapper.body:
{
  "model": "anthropic/claude-sonnet-4-6",
  "models": ["anthropic/claude-sonnet-4-6", "{{env.OPENROUTER_FALLBACK_MODEL}}"],
  "route": "fallback",
  "provider": { "allow_fallbacks": true },
  "messages": [
    {
      "role": "system",
      "content": "You are a trades job intake assistant. Extract information from the customer message and return ONLY a valid JSON object with these fields: job_type (string describing the type of work, e.g. 'plumbing repair', 'HVAC install', or null), address (full address string or null), urgency (one of: emergency, urgent, standard, flexible — based on language cues like 'ASAP', 'no heat', 'flooding', vs 'when you have time'), estimated_response_time (string: '15 minutes' for emergency, '2-4 hours' for urgent, 'same day' for standard, '1-2 business days' for flexible). Do not include any explanation or markdown."
    },
    {
      "role": "user",
      "content": "Customer message: {{1.body.messages[0].text}}"
    }
  ],
  "temperature": 0.1,
  "max_tokens": 256
}

{
  "actor_type": "agent",
  "actor_id": "{{env.FRESHCHAT_BOT_ID}}",
  "message_type": "normal",
  "message_parts": [
    {
      "text": {
        "content": "Hi {{1.body.actors[0].first_name}}, thanks for reaching out! We received your job request and a team member will be in touch shortly."
      }
    }
  ]
}

{
  "properties": {
    "dealname": "{{3.job_type}} — {{1.body.actors[0].first_name}} {{1.body.actors[0].last_name}} ({{formatDate(now; 'YYYY-MM-DD'; 'America/New_York')}})",
    "pipeline": "default",
    "dealstage": "{{env.HUBSPOT_STAGE_NEW_LEAD}}",
    "priority": "{{if(3.urgency == 'emergency'; 'HIGH'; if(3.urgency == 'urgent'; 'HIGH'; 'MEDIUM'))}}",
    "description": "Job Type: {{3.job_type}}
Address: {{3.address}}
Urgency: {{3.urgency}}
Estimated Response Time: {{3.estimated_response_time}}
Customer: {{1.body.actors[0].first_name}} {{1.body.actors[0].last_name}}
Email: {{1.body.actors[0].email}}
Phone: {{1.body.actors[0].phone}}
Freshchat Conversation ID: {{1.body.id}}
Original Message: {{1.body.messages[0].text}}
Received: {{formatDate(now; 'YYYY-MM-DD HH:mm:ss'; 'America/New_York')}} ET
Source: Trades Job Intake (Scenario AQ)"
  }
}

{
  "model": "anthropic/claude-sonnet-4-6",
  "models": ["anthropic/claude-sonnet-4-6", "{{env.OPENROUTER_FALLBACK_MODEL}}"],
  "route": "fallback",
  "provider": { "allow_fallbacks": true },
  "messages": [
    {
      "role": "system",
      "content": "You are a professional trades service assistant. Write a short, friendly confirmation message (2–3 sentences, no markdown) for a Freshchat chat window confirming a job request was received. Include the job type, address (if provided), and estimated response time. Keep the tone warm and reassuring."
    },
    {
      "role": "user",
      "content": "Customer first name: {{1.body.actors[0].first_name}}. Job type: {{3.job_type}}. Address: {{3.address}}. Urgency: {{3.urgency}}. Estimated response time: {{3.estimated_response_time}}."
    }
  ],
  "temperature": 0.4,
  "max_tokens": 200
}
